"""Write the requested checkpoint only after scientific/runtime checks pass."""
from common import *
import hashlib

def main():
    verification=json.loads((OUT/'stage10_verification.json').read_text());assert verification['passed']
    metric=pd.read_csv(OUT/'baseline_metrics.csv').set_index('model');ab=pd.read_csv(OUT/'ablation_results.csv').set_index('model');stress=pd.read_csv(OUT/'perturbation_results.csv').set_index('view');drift=pd.read_csv(OUT/'style_feature_drift.csv');border=json.loads((OUT/'border_sensitivity_summary.json').read_text());scores=pd.read_csv(OUT/'origin_silhouette_ari.csv');full=scores[scores.space.eq('full')]
    changes=[
        ('Control gate','Confirmed human/diffusion attribution','All comparisons descriptive; JPEG tables perfectly origin-aligned and subjects unavailable','No valid exchangeability or isolated origin effect can be established'),
        ('Permutation unit','Within-style artwork permutations','10000 whole-source-group label randomizations, preserving group counts; exploratory only','Avoids splitting known families; group sizes can differ and exchangeability still unsupported'),
        ('Null/uncertainty','Artwork-independent resampling','1000 whole-group bootstrap draws; within-origin disjoint group split halves (1000 each origin)','Correlated artist/source families preserved; confidence conditional on observed sources'),
        ('Unsupervised clustering','scikit-learn KMeans','NumPy Lloyd k2, 20 seeded k-means++ starts, max300 iterations','Host Application Control blocked sklearn native DLL; no policy changes made'),
        ('Fourth feature family','HSV/Edges','Color/edges includes both HSV and cached Lab measurements; explicit HSV/Lab/combined ablations','Additional color representation is not silently merged into the requested four-family labels'),
        ('Full-canvas geometry','Same crop feature dimension','Single full256 measurement vector without across-crop IQR duplicates','Geometry comparison also changes dimension; four vs five crops retains104 dimensions'),
        ('Silhouette uncertainty','Refit/recompute geometry in each bootstrap','Paired bootstrap of cached per-artwork silhouette scores in fixed variant geometry','Intervals omit uncertainty from re-estimating pairwise geometry'),
        ('Unmatched control ablation','All185015 pixels mixed native256/768','Full 185,015 native metadata probes plus frozen 45,000 mixed-origin pixel cohort, SD resized256','Tier2 pixel budget retained; source mixture differs, so not a causal isolation of resolution'),
        ('Boundary sensitivity','Remove boundary dominated crops','Fixed luminance-strip heuristic; compare both arms on identical 5,924 supported test artworks','76 all-flagged artworks unsupported; heuristic is not a verified frame annotation'),
        ('Failure labels','Named artwork subjects/materials','Development-quantile saturation/edge/high-frequency proxies and fixed border heuristic','No semantic subject, genre or paint-material labels inferred'),
        ('JPEG original reference','Q100 pristine image','Original release JPEG; recompress95/75/50','Original is already lossy; Q100 label is a plotting reference, not pristine ground truth'),
        ('Discriminative display features','Top test effects','Six largest absolute coefficients of the frozen development-trained primary probe','No feature ranking on test outcomes'),
        ('Unsupported example movements','Cubism/Pointillism examples','Use only the actual ten release styles; representative Renaissance/Impressionism/Ukiyo-e','No invented style labels'),
        ('Dashboard table rendering','Arrow-backed interactive tables','Streamlit+Plotly charts, HTML read-only tables, CSV download, fastparquet','Avoids the host-blocked optional Arrow DLL; filters/drilldown remain interactive'),
    ]
    pd.DataFrame(changes,columns=['Methodology step','Original design','Implementation / adjustment','Validity impact / reason']).to_csv(OUT/'methodology_changes.csv',index=False)
    gallery=pd.read_csv(OUT/'error_gallery_cases.csv');observations=[]
    notes={'2f0c78f46f':'Repeating ornament fills most of the canvas.','305d3cd479':'A landscape and reclining figure share the canvas.','e679eb4f82':'Prominent typographic lettering over a textured field.','6c9f139321':'Prominent light lettering over a textured field.','f3fa732e66':'Ornate framing occupies much of the canvas.','89f0f4d605':'Ornate framing surrounds the portrait.','f4af268f19':'Decorative object photographed against a pale background.','a1dce1b036':'Near-monochrome graphic with strong edge structure; hue resultant undefined.'}
    for r in gallery.itertuples():
        prefix=str(r.artwork_id)[:10]
        if prefix in notes:observations.append(dict(artwork_id=r.artwork_id,selection_reason=r.selection_reason,observation=notes[prefix],evidence='Direct visual inspection of held-out gallery artwork; qualitative, not independently annotated or a prevalence estimate.'))
    pd.DataFrame(observations).to_csv(OUT/'forensic_visual_observations.csv',index=False)
    for filename in ['stage6_protocol.json','stage7_8_protocol.json']:
        record=json.loads((OUT/filename).read_text());record['runtime_scope']='Successful invocation including cache loading; completed batches may come from earlier invocation(s). This is not a reconstruction of total experiment wall time.';save_json(filename,record)
    summary=['# Stage 10 checkpoint','', 'Completed through Stage 10; stopped before Stages 11–12. All existing Stage 5 encoder/probe caches were reused; both 45,000-row CUDA embedding caches were already complete when this resume began.','',
        '**Interpretation:** all origin comparisons remain descriptive. JPEG quantization is deterministically origin-aligned (gated metadata AUROC 1.0), and prompt/subject matches cannot be verified. There are no statistically confirmed origin-drift cells.','',
        '## Five empirical findings','',
        f"1. On the same 6,000 Human/LD test artworks, AUROC: handcrafted {metric.loc['handcrafted','roc_auc']:.12f}; ResNet50 {metric.loc['resnet50','roc_auc']:.12f}; DINOv2 {metric.loc['dinov2','roc_auc']:.12f}; FFT-only {metric.loc['frequency','roc_auc']:.12f}; metadata {metric.loc['metadata_gated','roc_auc']:.12f}.",
        f"2. Of {len(drift)} prespecified feature×style tests, {int(drift.raw_rule_pass.sum())} pass the exploratory BH+split-half-null rule; confirmed cells: {int(drift.confirmed_drift.sum())}. Each style used 10,000 whole-group randomizations and 1,000 source-group bootstrap resamples; within-origin nulls pool 1,000 disjoint group split-halves per origin.",
        f"3. Removing ordinal features changes AUROC by {ab.loc['ab_without_Ordinal','delta_auc']:.12f}, to {ab.loc['ab_without_Ordinal','roc_auc']:.12f}. Full 256 canvas gives {ab.loc['ab_full_canvas','roc_auc']:.12f}, five crops {ab.loc['ab_five_crop','roc_auc']:.12f}; original four crops {metric.loc['handcrafted','roc_auc']:.12f}.",
        f"4. JPEG50 reduces frozen-probe AUROC to {stress.loc['jpeg50','roc_auc']:.12f}, with style-W1 rank rho {stress.loc['jpeg50','style_w1_rank_rho']:.12f}; resize 0.5 gives AUROC {stress.loc['resize0.5','roc_auc']:.12f}. Severe recompression can increase silhouette while reducing origin-classification performance; separation alone is not detector quality.",
        f"5. Border heuristic flags {border['flagged_artworks']} artworks; {border['all_crops_excluded']} have no usable quadrant. Paired sensitivity on {border['paired_supported_n']} artworks changes {border['direction_reversals']} signed feature/style directions and {border['exploratory_rule_reversals']} exploratory rule outcomes; zero confirmatory conclusions in either arm. Full-space k-means ARI ranges {full.ari.min():.12f}–{full.ari.max():.12f}, showing weak agreement despite high supervised AUC.",
        '', '## Deliverables','',
        '- Ten named fig01–fig10 composites at 300 DPI, captions in FIGURE_CAPTIONS.md, index in figure_manifest.csv. All ten visually inspected; PCA labels and baseline legend spacing refined.',
        '- Drift: style_feature_drift.csv, style_family_drift.csv, sliced_wasserstein.csv, origin_silhouette_ari.csv, interstyle_centroid_distances.csv; complete permutation/split-half samples in drift_parts/.',
        '- Ablations/robustness: ablation_results.csv, color_saturation_ablation.csv, control_gate_ablation.csv, perturbation_results.csv, perturbation_auc_intervals.csv, perturbed_style_w1.csv; conditional paired source-group intervals.',
        '- Forensics: error_gallery_cases.csv, gallery/ artwork/quadrant PNGs, failure_trigger_rates.csv, failure_trigger_associations.csv, border_exclusion_drift.csv, border_paired_statistical_tests.csv; complete paired null samples in border_stats_parts/.',
        '- Literature: literature_comparison.csv includes 18 verified claim records from 16 unique papers plus five OURS rows; every external number copied verbatim from literature_facts.csv with version/page and non-comparability caveats.',
        '- Local interactive dashboard: ../src/dashboard.py; Streamlit+Plotly raw/hex views, fixed axes/bins, movement/origin filters, fidelity badges, artwork selection/drilldown, baseline/drift/ablation/forensic/figure/literature tabs.',
        f"- Fresh-process verification: {verification['checks']} checks passed (stage10_integrity_checks.csv), including cached prediction reproduction for all five primary and thirteen ablation probes, independent W1/FDR recomputation, IDs/splits/manifest, null shapes, evidence claims, figure DPI and dashboard runtime checks. Three targeted numerical checks added; original seven feature tests preserved.",
        '', '## Adjustments and reference discrepancies','',
        'methodology_changes.csv records the full scoped adjustments, rationale and validity cost. Earlier decisions remain in CONTROL_GATE_LIMITATIONS.md and REVIEW_NOTES.md. Native-dimension control did not remove encoding leakage; this negative result is preserved in figures and dashboard.',
        'The18 bibliography entries contain 16 unique papers (duplicate SPAI and SCADET entries). Two Phase 1 author entries needed correction (Kong et al.; Li/Lu/Song/Cheng). Version mismatches and unresolved headline claims were kept version-scoped or excluded. ArtBrain joint source/style F1 is not our binary endpoint; AP is not AUROC; MisVisFix issue identification is not projection accuracy. See literature_crosswalk.csv, literature_facts.csv and REVIEW_NOTES.md for exact provenance.',
        '', '## Launch dashboard (PowerShell)','', '```powershell', "$env:PIP_CACHE_DIR='D:\\Dev\\pip_cache'", "$env:TEMP='D:\\Dev\\tmp'", "& 'D:\\Dev\\envs\\dav_phase3\\python.exe' -m streamlit run '"+str(ROOT/'src/dashboard.py')+"'", '```','',
        'No dashboard server is left running. No final DOCX/PDF was requested for this checkpoint; those belong to Stage 11. The Stage 12 report/document gates remain unrun. Stage 10 includes its own fresh-process numerical/runtime integrity checks.','']
    summary='\n'.join(summary)
    historical=OUT/'CHECKPOINT_SUMMARY_STAGE5.md'
    if not historical.exists():historical.write_text((OUT/'CHECKPOINT_SUMMARY.md').read_text(encoding='utf-8'),encoding='utf-8')
    for filename in ['CHECKPOINT_SUMMARY.md','FINAL_SUMMARY.md']:(OUT/filename).write_text(summary,encoding='utf-8')
    with (OUT/'REVIEW_NOTES.md').open('a',encoding='utf-8') as stream:stream.write('\n\n## Stage6–10 scoped review\n\n'+ '\n'.join('- '+r[0]+': '+r[2]+'. '+r[3]+'.' for r in changes)+'\n\nReviewed all ten composites, fixed overlapping PCA/ARI labels and moved bar legends. Border comparisons rerun on the same supported artwork IDs in both arms, with separate 1,040-test BH correction per arm. Figure family stars label constituent exploratory passes rather than family-level significance. Quantization/subject limitations are shown in every figure caption and the dashboard. Fresh-process verification results are in stage10_integrity_checks.csv.\n')
    inventory=[dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size) for p in OUT.rglob('*') if p.is_file()];pd.DataFrame(inventory).to_csv(OUT/'stage10_artifact_inventory.csv',index=False)
    save_json('stage10_source_hashes.json',{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for folder in ['src','tests'] for p in (ROOT/folder).glob('*.py')})
    progress('Stage 10 complete — checkpoint verified',f"Completed Stages 0–10. Reused completed 45,000-row ResNet50/DINOv2 CUDA caches; original manifest unchanged. Stages6–9 drift, ablations, robustness, paired border analysis, eight actual forensic cases and 18 literature claim comparisons complete. All ten named 300-DPI composites saved to results/ and visually reviewed; src/dashboard.py passed eight actual Streamlit runtime scenarios. {verification['checks']} fresh-process integrity checks passed. Exploratory feature/style rule passes: {int(drift.raw_rule_pass.sum())}/{len(drift)}; confirmed drift: 0 (subjects unverified, JPEG quantization origin-aligned). results/FINAL_SUMMARY.md and methodology_changes.csv give outcomes, caveats and launch command. No active runner or dashboard server. Stopped before Stages 11–12 as requested.")
    print('Stage 10 finalized',flush=True)
if __name__=='__main__':main()
